515	func (p *Parser) parseStructDecl() (*ast.Node, error) {
516		structNode := &ast.Node{
517			Kind: ast.NodeStructDecl,
518			Line: p.curToken.Line,
519			Col:  p.curToken.Col,
520		}
521	
522		p.nextToken() // consume 'struct'
523	
524		if p.curToken.Type != ast.TokenIdent {
525			return nil, fmt.Errorf("expected struct name")
526		}
527	
528		structNode.Value = p.curToken.Value
529		p.nextToken()
530	
531		if p.curToken.Type != ast.TokenLBrace {
532			return nil, fmt.Errorf("expected '{' after struct name")
533		}
534	
535		p.nextToken() // consume '{'
536	
537		// Parse fields
538		for p.curToken.Type != ast.TokenRBrace {
539			field, err := p.parseFieldDecl()
540			if err != nil {
541				return nil, err
542			}
543			structNode.Children = append(structNode.Children, field)
544	
545			if p.curToken.Type == ast.TokenSemicolon {
546				p.nextToken()
547			}
548		}
549	
550		p.nextToken() // consume '}'
551	
552		return structNode, nil
553	}
