593	// parseStructLit parses struct initialization: Point{x: 1, y: 2}
594	func (p *Parser) parseStructLit(name string) (*ast.Node, error) {
595		structLit := &ast.Node{
596			Kind:  ast.NodeStructLit,
597			Value: name,
598			Line:  p.curToken.Line,
599			Col:   p.curToken.Col,
600		}
601	
602		p.nextToken() // consume '{'
603	
604		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
605			if p.curToken.Type != ast.TokenIdent {
606				return nil, fmt.Errorf("expected field name in struct init")
607			}
608	
609			fieldName := p.curToken.Value
610			p.nextToken()
611	
612			if p.curToken.Type != ast.TokenColon {
613				return nil, fmt.Errorf("expected ':' after field name in struct init")
614			}
615	
616			p.nextToken()
617	
618			// Parse field value expression
619			fieldValue, err := p.parseExpression(0)
620			if err != nil {
621				return nil, err
622			}
623	
624			// Create field initialization node
625			fieldInit := &ast.Node{
626				Kind:  ast.NodeFieldDecl,
627				Value: fieldName,
628			}
629			fieldInit.Children = append(fieldInit.Children, fieldValue)
630			structLit.Children = append(structLit.Children, fieldInit)
631	
632			if p.curToken.Type == ast.TokenComma {
633				p.nextToken()
634			}
635		}
636	
637		if p.curToken.Type != ast.TokenRBrace {
638			return nil, fmt.Errorf("expected '}' to close struct init")
639		}
640	
641		p.nextToken() // consume '}'
642	
643		return structLit, nil
644	}
