53	// Truthy returns whether a value is truthy in a conditional context
54	func (v Value) Truthy() bool {
55		switch v.Kind {
56		case KindNil:
57			return false
58		case KindBool:
59			return v.BVal
60		case KindInt:
61			return v.IVal != 0
62		case KindString:
63			return v.SVal != ""
64		case KindArray:
65			return len(v.Elems) > 0
66		case KindStruct:
67			return len(v.Fields) > 0
68		default:
69			return true
70		}
71	}
