101	// ToInterface converts a Value to interface{} for builtin function calls
102	func (v Value) ToInterface() interface{} {
103		switch v.Kind {
104		case KindNil:
105			return nil
106		case KindInt:
107			return v.IVal
108		case KindBool:
109			return v.BVal
110		case KindString:
111			return v.SVal
112		case KindArray:
113			result := make([]interface{}, len(v.Elems))
114			for i, e := range v.Elems {
115				result[i] = e.ToInterface()
116			}
117			return result
118		case KindStruct:
119			return map[string]interface{}{"_type": "struct"}
120		default:
121			return nil
122		}
123	}
124	
125	// FromInterface creates a Value from interface{} (builtin return values)
126	func FromInterface(v interface{}) Value {
127		if v == nil {
128			return NilVal()
129		}
130	
131		switch val := v.(type) {
132		case int:
133			return IntVal(int64(val))
134		case int64:
135			return IntVal(val)
136		case bool:
137			return BoolVal(val)
138		case string:
139			return StringVal(val)
140		case []interface{}:
141			elems := make([]Value, len(val))
142			for i, e := range val {
143				elems[i] = FromInterface(e)
144			}
145			return ArrayVal(elems)
146		case []string:
147			elems := make([]Value, len(val))
148			for i, s := range val {
149				elems[i] = StringVal(s)
150			}
151			return ArrayVal(elems)
152		default:
153			return NilVal()
154		}
155	}
